migrations.sql:
-- D1 is authoritative. Every domain mutation atomically compares revision.
CREATE TABLE workspace (
 id INTEGER PRIMARY KEY CHECK (id = 1),
 revision INTEGER NOT NULL CHECK (revision >= 0),
 document TEXT NOT NULL CHECK (json_valid(document)),
 schema_version INTEGER NOT NULL CHECK (schema_version = 1)
);
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, name TEXT NOT NULL);
INSERT INTO schema_migrations VALUES(1, 'workspace-document-v1');

-- Preserve v1 data and ledger; add private attachment lifecycle to the document.
CREATE TABLE workspace_v2 (
 id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL CHECK(revision>=0),
 document TEXT NOT NULL CHECK(json_valid(document)),schema_version INTEGER NOT NULL CHECK(schema_version=2)
);
INSERT INTO workspace_v2 SELECT id,revision,json_set(document,'$.schemaVersion',2,'$.attachments',json('[]')),2 FROM workspace;
-- substr strips SQLite's JSON subtype so the immutable payload stays a string.
UPDATE workspace_v2 SET document=json_set(document,'$.messages',json((SELECT coalesce(json_group_array(json(CASE WHEN json_extract(value,'$.payload')='[erased]' THEN value ELSE json_set(value,'$.payload',substr(json_set(json_extract(value,'$.payload'),'$.attachments',json('[]')),1)) END)),'[]') FROM json_each(document,'$.messages'))));
DROP TABLE workspace;
ALTER TABLE workspace_v2 RENAME TO workspace;
INSERT INTO schema_migrations VALUES(2,'private-attachments-v2');

-- Native schema3 maps root ledger5 attention; prior identities and erased markers remain.
CREATE TABLE workspace_v3 (
 id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL CHECK(revision>=0),
 document TEXT NOT NULL CHECK(json_valid(document)),schema_version INTEGER NOT NULL CHECK(schema_version=3)
);
INSERT INTO workspace_v3 SELECT id,revision,json_set(document,'$.schemaVersion',3,'$.preferences',json('[]'),'$.thread_follows',json('[]'),'$.user_settings',json('[]'),'$.attention',json('[]')),3 FROM workspace;
UPDATE workspace_v3 SET document=json_set(document,'$.messages',json((SELECT coalesce(json_group_array(json(CASE WHEN json_extract(value,'$.payload')='[erased]' THEN value ELSE json_set(value,'$.payload',substr(json_set(json_extract(value,'$.payload'),'$.mentions',json('[]'),'$.urgent',json('false'),'$.urgentReason',NULL),1)) END)),'[]') FROM json_each(document,'$.messages'))));
DROP TABLE workspace;
ALTER TABLE workspace_v3 RENAME TO workspace;
INSERT INTO schema_migrations VALUES(3,'calm-attention-v3');

-- Add immutable external history without changing applied migrations or event frontiers.
CREATE TABLE workspace_v4 (
 id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL CHECK(revision>=0),
 document TEXT NOT NULL CHECK(json_valid(document)),schema_version INTEGER NOT NULL CHECK(schema_version=4)
);
INSERT INTO workspace_v4 SELECT id,revision,json_set(document,'$.schemaVersion',4,'$.imports',json('[]')),4 FROM workspace;
DROP TABLE workspace;
ALTER TABLE workspace_v4 RENAME TO workspace;
INSERT INTO schema_migrations(version,name) VALUES(4,'immutable-imports-v4');

-- Additive local-development storage. Apply explicitly to the local D1 database.
CREATE TABLE IF NOT EXISTS rer_mail_development_outbox (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  message TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS rer_mail_development_outbox_order
  ON rer_mail_development_outbox(created_at DESC, sequence DESC);

CREATE TABLE rer_portability_state (
  id INTEGER PRIMARY KEY CHECK(id=1), source_identity TEXT NOT NULL, epoch INTEGER NOT NULL DEFAULT 0,
  import_job TEXT, applying INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE rer_portability_jobs (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, actor TEXT NOT NULL, phase TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL
);
CREATE TABLE rer_portability_parts (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  idx INTEGER NOT NULL, sha256 TEXT NOT NULL, PRIMARY KEY(job,idx)
);
CREATE TABLE rer_portability_segments (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  part INTEGER NOT NULL, segment INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(job,part,segment)
);
CREATE TABLE rer_portability_owned (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  bucket TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY(job,bucket,key)
);
CREATE TABLE rer_portability_journal (
  source TEXT NOT NULL, tombstone TEXT NOT NULL, PRIMARY KEY(source,tombstone)
);
CREATE TABLE rer_portability_epochs (source TEXT PRIMARY KEY, epoch INTEGER NOT NULL);
CREATE TABLE rer_portability_guard (value INTEGER NOT NULL CHECK(value=1));

-- Append-only authority transition. Existing installations stay paused until the
-- explicit offline converter validates and atomically cuts over.
CREATE TABLE nook_storage(id INTEGER PRIMARY KEY CHECK(id=1),authority TEXT NOT NULL CHECK(authority IN ('legacy','normalized')),phase TEXT NOT NULL);
INSERT INTO nook_storage SELECT 1,CASE WHEN EXISTS(SELECT 1 FROM workspace) THEN 'legacy' ELSE 'normalized' END,'ready';
CREATE TABLE nook_guard(id TEXT PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE nook_actors(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT,role TEXT,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE TABLE nook_conversations(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('channel','private','dm')),owner TEXT NOT NULL,seq INTEGER NOT NULL DEFAULT 0 CHECK(seq>=0),version INTEGER NOT NULL DEFAULT 1,message_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE nook_members(conversation TEXT NOT NULL REFERENCES nook_conversations(id),user TEXT NOT NULL,PRIMARY KEY(conversation,user));
CREATE INDEX nook_member_directory ON nook_members(user,conversation);
CREATE TABLE nook_messages(id TEXT PRIMARY KEY,conversation TEXT NOT NULL REFERENCES nook_conversations(id),author TEXT NOT NULL,body TEXT NOT NULL,body_lower TEXT NOT NULL,parent TEXT,version INTEGER NOT NULL,deleted INTEGER NOT NULL CHECK(deleted IN (0,1)),created TEXT NOT NULL,intent TEXT NOT NULL,payload TEXT NOT NULL,sequence INTEGER NOT NULL,ordinal INTEGER NOT NULL,author_ordinal INTEGER NOT NULL,UNIQUE(conversation,author,intent),UNIQUE(conversation,sequence));
CREATE INDEX nook_history_cursor ON nook_messages(conversation,(created||id));
CREATE INDEX nook_message_author ON nook_messages(conversation,author,sequence);
CREATE INDEX nook_thread_history ON nook_messages(conversation,parent,sequence);
CREATE INDEX nook_unread_author ON nook_messages(conversation,author,sequence) WHERE deleted=0;
CREATE TABLE nook_revisions(message TEXT NOT NULL REFERENCES nook_messages(id),version INTEGER NOT NULL,body TEXT NOT NULL,at TEXT NOT NULL,PRIMARY KEY(message,version));
CREATE TABLE nook_events(conversation TEXT NOT NULL REFERENCES nook_conversations(id),seq INTEGER NOT NULL,kind TEXT NOT NULL,object TEXT NOT NULL,actor TEXT,PRIMARY KEY(conversation,seq));
CREATE TABLE nook_outcomes(id TEXT PRIMARY KEY,conversation TEXT NOT NULL REFERENCES nook_conversations(id),author TEXT NOT NULL,assignee TEXT,kind TEXT NOT NULL,body TEXT NOT NULL,source TEXT,source_version INTEGER,version INTEGER NOT NULL,status TEXT NOT NULL,deadline TEXT);
CREATE INDEX nook_outcome_scope ON nook_outcomes(conversation,id);
CREATE INDEX nook_outcome_source ON nook_outcomes(source);
CREATE TABLE nook_outcome_versions(outcome TEXT NOT NULL REFERENCES nook_outcomes(id),version INTEGER NOT NULL,actor TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,deadline TEXT,PRIMARY KEY(outcome,version));
CREATE TABLE nook_reads(conversation TEXT NOT NULL,user TEXT NOT NULL,seq INTEGER NOT NULL,total INTEGER NOT NULL DEFAULT 0,own INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(conversation,user));
CREATE TABLE nook_preferences(user TEXT NOT NULL,conversation TEXT NOT NULL,muted INTEGER NOT NULL DEFAULT 0,followed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user,conversation));
CREATE TABLE nook_thread_follows(user TEXT NOT NULL,message TEXT NOT NULL,PRIMARY KEY(user,message));
CREATE TABLE nook_settings(user TEXT PRIMARY KEY,dnd_until INTEGER);
CREATE TABLE nook_attention(id TEXT PRIMARY KEY,user TEXT NOT NULL,conversation TEXT NOT NULL,event_seq INTEGER NOT NULL,message TEXT,outcome TEXT,reason TEXT NOT NULL,state TEXT NOT NULL,snooze_until INTEGER,created TEXT NOT NULL,UNIQUE(user,conversation,event_seq));
CREATE INDEX nook_attention_inbox ON nook_attention(user,conversation,state,id);
CREATE INDEX nook_attention_deadline ON nook_attention(user,conversation,state,snooze_until);
CREATE TABLE nook_attachments(id TEXT PRIMARY KEY,conversation TEXT NOT NULL,author TEXT NOT NULL,message TEXT,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT,expires INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('reserved','staged','attached','deleted')),created TEXT NOT NULL,object_key TEXT UNIQUE,intent TEXT NOT NULL,position INTEGER,UNIQUE(author,intent));
CREATE INDEX nook_attachment_message ON nook_attachments(message,position);
CREATE INDEX nook_attachment_staged ON nook_attachments(author,state,expires);
CREATE TABLE nook_object_deletes(object_key TEXT PRIMARY KEY,created INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0);
-- FTS5 trigram indexes exact substrings of length >=3. Short queries are
-- rejected explicitly rather than silently degenerating to a table scan.
CREATE VIRTUAL TABLE nook_search USING fts5(message UNINDEXED,conversation UNINDEXED,source,scope,body_lower,tokenize='trigram case_sensitive 1');
CREATE TABLE nook_imports(id TEXT PRIMARY KEY,owner TEXT NOT NULL,intent TEXT NOT NULL,plan_digest TEXT NOT NULL,capture_digest TEXT NOT NULL,created TEXT NOT NULL,namespace TEXT NOT NULL,preview_digest TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('staging','complete')),UNIQUE(owner,intent));
CREATE TABLE nook_import_channels(job TEXT NOT NULL,source_id TEXT NOT NULL,conversation TEXT NOT NULL UNIQUE,source_record TEXT NOT NULL,PRIMARY KEY(job,source_id));
CREATE TABLE nook_import_actors(job TEXT NOT NULL,source_id TEXT NOT NULL,association TEXT,source_record TEXT NOT NULL,PRIMARY KEY(job,source_id));
CREATE TABLE nook_import_records(id TEXT PRIMARY KEY,job TEXT NOT NULL,key TEXT NOT NULL UNIQUE,conversation TEXT NOT NULL,source_actor TEXT NOT NULL,source_timestamp TEXT NOT NULL,source_record TEXT NOT NULL,body TEXT NOT NULL,body_lower TEXT NOT NULL,parent TEXT,sequence INTEGER NOT NULL,UNIQUE(conversation,sequence));
CREATE TABLE nook_import_files(id TEXT PRIMARY KEY,job TEXT NOT NULL,message TEXT NOT NULL,source_id TEXT NOT NULL,attachment TEXT NOT NULL,position INTEGER NOT NULL);
CREATE INDEX nook_import_file_message ON nook_import_files(message,position);
CREATE TABLE nook_import_receipts(job TEXT NOT NULL,path TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(job,path,sha256));
CREATE TABLE nook_conversion(id INTEGER PRIMARY KEY CHECK(id=1),source_revision INTEGER NOT NULL,source_digest TEXT NOT NULL,phase TEXT NOT NULL,counts TEXT NOT NULL);
INSERT INTO schema_migrations VALUES(5,'normalized-storage-v5');

CREATE TABLE nook_author_counts(conversation TEXT NOT NULL,user TEXT NOT NULL,total INTEGER NOT NULL,PRIMARY KEY(conversation,user));
INSERT INTO nook_actors SELECT id,display_name,email,role,CASE WHEN status='active' THEN 1 ELSE 0 END FROM oa_operators;
CREATE TRIGGER nook_actor_created AFTER INSERT ON oa_operators BEGIN
 INSERT INTO nook_actors VALUES(NEW.id,NEW.display_name,NEW.email,NEW.role,CASE WHEN NEW.status='active' THEN 1 ELSE 0 END)
 ON CONFLICT(id) DO UPDATE SET name=excluded.name,email=excluded.email,role=excluded.role,active=excluded.active;
END;
CREATE TRIGGER nook_actor_updated AFTER UPDATE OF display_name,email,role,status ON oa_operators BEGIN
 UPDATE nook_actors SET name=NEW.display_name,email=NEW.email,role=NEW.role,active= CASE WHEN NEW.status='active' THEN 1 ELSE 0 END WHERE id=NEW.id;
END;
-- Every in-flight put is durable. Deletion cannot race a late writer. Interrupted
-- attempts are reconciled only by the explicit paused operator command.
CREATE TABLE nook_upload_attempts(id TEXT PRIMARY KEY,object_key TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX nook_upload_attempt_object ON nook_upload_attempts(object_key);

-- Product admission is explicit and separate from Base operator roles.
CREATE TABLE nook_access(user TEXT PRIMARY KEY REFERENCES nook_actors(id),mode TEXT NOT NULL CHECK(mode IN ('member','guest')),active INTEGER NOT NULL CHECK(active IN (0,1)),generation INTEGER NOT NULL DEFAULT 1);
CREATE TABLE nook_guest_grants(user TEXT NOT NULL REFERENCES nook_access(user),conversation TEXT NOT NULL REFERENCES nook_conversations(id),PRIMARY KEY(user,conversation));
CREATE TABLE nook_invite_plans(id TEXT PRIMARY KEY,email TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','admin','member')),mode TEXT NOT NULL CHECK(mode IN ('member','guest')),scopes TEXT NOT NULL CHECK(json_valid(scopes) AND json_type(scopes)='array'),generation INTEGER NOT NULL CHECK(generation>0),issuer TEXT NOT NULL,issuer_version INTEGER NOT NULL,issuer_session TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('prepared','accepted','cancelled')),prepared_at INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec')*1000 AS INTEGER)),CHECK(mode='member' OR role='member'));
CREATE UNIQUE INDEX nook_invite_current ON nook_invite_plans(email) WHERE state<>'cancelled';
CREATE TABLE nook_creator_revocations(conversation TEXT PRIMARY KEY REFERENCES nook_conversations(id),user TEXT NOT NULL REFERENCES nook_actors(id),generation INTEGER NOT NULL,event_seq INTEGER NOT NULL);
CREATE TABLE nook_dm_roster(conversation TEXT NOT NULL,user TEXT NOT NULL,PRIMARY KEY(conversation,user));
INSERT INTO nook_dm_roster SELECT m.conversation,m.user FROM nook_members m JOIN nook_conversations c ON c.id=m.conversation WHERE c.kind='dm';
CREATE TABLE nook_reactions(message TEXT NOT NULL REFERENCES nook_messages(id),user TEXT NOT NULL REFERENCES nook_actors(id),emoji TEXT NOT NULL CHECK(emoji IN ('👍','❤️','🎉','👀','✅','🙌')),created TEXT NOT NULL,PRIMARY KEY(message,user,emoji));
CREATE INDEX nook_reaction_message ON nook_reactions(message,emoji,user);
-- Admit only identities already explicitly represented in the product at upgrade.
INSERT INTO nook_access SELECT a.id,'member',CASE WHEN o.status='active' AND a.active=1 THEN 1 ELSE 0 END,1 FROM nook_actors a JOIN oa_operators o ON o.id=a.id;
INSERT OR IGNORE INTO nook_actors SELECT o.id,o.display_name,o.email,o.role,1 FROM oa_operators o JOIN oa_bootstrap b ON b.claim_id=o.id WHERE o.status='active';
INSERT OR IGNORE INTO nook_access SELECT o.id,'member',1,1 FROM oa_operators o JOIN oa_bootstrap b ON b.claim_id=o.id WHERE o.status='active';
-- Actor activation records current product admission, not merely a usable login.
DROP TRIGGER nook_actor_updated;
CREATE TRIGGER nook_actor_updated AFTER UPDATE OF display_name,email,role,status ON oa_operators BEGIN
 UPDATE nook_actors SET name=NEW.display_name,email=NEW.email,role=NEW.role,active= CASE WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM nook_access WHERE user=NEW.id AND active=1) THEN 1 ELSE 0 END WHERE id=NEW.id;
END;
CREATE TRIGGER nook_bootstrap_access AFTER INSERT ON oa_operators WHEN NEW.status='active' AND NEW.role='owner' AND EXISTS(SELECT 1 FROM oa_bootstrap WHERE claim_id=NEW.id)
BEGIN INSERT OR IGNORE INTO nook_actors VALUES(NEW.id,NEW.display_name,NEW.email,NEW.role,1); INSERT INTO nook_access VALUES(NEW.id,'member',1,1); END;
-- Prepared plans carry exactly one durable scope set. A changed pending scope
-- conflicts; cancel the actual Base invitation before preparing a new generation.
CREATE TRIGGER nook_plan_validate BEFORE INSERT ON nook_invite_plans
BEGIN
 SELECT CASE WHEN NEW.email<>lower(trim(NEW.email)) OR NEW.state<>'prepared' OR json_array_length(NEW.scopes)<1 OR json_array_length(NEW.scopes)>50 OR (SELECT count(DISTINCT value) FROM json_each(NEW.scopes))<>json_array_length(NEW.scopes) THEN RAISE(ABORT,'invalid_invitation_scope') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM oa_operators o JOIN oa_sessions s ON s.operator_id=o.id JOIN nook_access a ON a.user=o.id WHERE o.id=NEW.issuer AND o.status='active' AND o.version=NEW.issuer_version AND (o.role='owner' OR o.role='admin' AND NEW.role='member') AND a.active=1 AND a.mode='member' AND s.id=NEW.issuer_session AND s.operator_version=o.version AND s.revoked_at IS NULL AND s.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER)) THEN RAISE(ABORT,'inviter_authority_changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.scopes) j WHERE j.type<>'text' OR NOT EXISTS(SELECT 1 FROM nook_conversations c JOIN nook_members m ON m.conversation=c.id WHERE c.id=j.value AND c.kind<>'dm' AND m.user=NEW.issuer AND (SELECT count(*) FROM nook_members capacity WHERE capacity.conversation=c.id)<50)) THEN RAISE(ABORT,'invalid_invitation_scope') END;
END;
CREATE TRIGGER nook_plan_immutable BEFORE UPDATE OF id,email,role,mode,scopes,generation,issuer,issuer_version,issuer_session,prepared_at ON nook_invite_plans BEGIN SELECT RAISE(ABORT,'invitation_scope_immutable'); END;
CREATE TRIGGER nook_plan_delete BEFORE DELETE ON nook_invite_plans WHEN OLD.state<>'cancelled' BEGIN SELECT RAISE(ABORT,'cancel_invitation_first'); END;
-- Acceptance is witnessed by the actual source-token-bound Base session. An
-- auth-only invitation has no witness in the product ledger and stays denied.
CREATE TRIGGER nook_invite_accept BEFORE UPDATE OF status ON oa_operators WHEN OLD.status='invited' AND NEW.status='active'
BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1 AND (NOT EXISTS(SELECT 1 FROM oa_operators i JOIN nook_access a ON a.user=i.id WHERE i.id=p.issuer AND i.status='active' AND i.version=p.issuer_version AND a.active=1 AND a.mode='member' AND (i.role='owner' OR i.role='admin' AND p.role='member')) OR EXISTS(SELECT 1 FROM json_each(p.scopes) j WHERE NOT EXISTS(SELECT 1 FROM nook_conversations c JOIN nook_members m ON m.conversation=c.id WHERE c.id=j.value AND c.kind<>'dm' AND m.user=p.issuer AND (SELECT count(*) FROM nook_members capacity WHERE capacity.conversation=c.id)<50)))) THEN RAISE(ABORT,'invitation_scope_changed') END;
END;
CREATE TRIGGER nook_invite_grant AFTER UPDATE OF status ON oa_operators WHEN OLD.status='invited' AND NEW.status='active'
BEGIN
 INSERT INTO nook_actors VALUES(NEW.id,NEW.display_name,NEW.email,NEW.role,1) ON CONFLICT(id) DO UPDATE SET name=excluded.name,email=excluded.email,role=excluded.role,active=1;
 INSERT INTO nook_access SELECT NEW.id,p.mode,1,p.generation FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1 ON CONFLICT(user) DO UPDATE SET mode=excluded.mode,active=1,generation=excluded.generation;
 INSERT INTO nook_guest_grants SELECT NEW.id,j.value FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at,json_each(p.scopes) j WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1 AND p.mode='guest';
 INSERT INTO nook_members SELECT j.value,NEW.id FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at,json_each(p.scopes) j WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1;
 UPDATE nook_invite_plans SET state='accepted' WHERE id IN (SELECT p.id FROM oa_sessions s JOIN oa_tokens t ON t.id=s.source_token_id AND t.kind='invite' AND t.operator_id=s.operator_id JOIN nook_invite_plans p ON p.email=NEW.email AND p.role=NEW.role AND p.issuer=t.issuer_id AND p.issuer_version=t.issuer_version AND p.state='prepared' AND p.prepared_at<=t.created_at WHERE s.operator_id=NEW.id AND s.operator_version=OLD.version+1);
END;
CREATE TRIGGER nook_deactivate AFTER UPDATE OF status ON oa_operators WHEN NEW.status='inactive' AND OLD.status<>NEW.status
BEGIN
 UPDATE oa_sessions SET revoked_at=COALESCE(revoked_at,CAST(unixepoch('subsec')*1000 AS INTEGER)) WHERE operator_id=NEW.id;
 UPDATE nook_access SET active=0,generation=generation+1 WHERE user=NEW.id;
 UPDATE nook_actors SET active=0 WHERE id=NEW.id;
 DELETE FROM nook_members WHERE user=NEW.id;
 DELETE FROM nook_guest_grants WHERE user=NEW.id;
 UPDATE nook_invite_plans SET state='cancelled' WHERE email=NEW.email AND state='prepared';
END;
CREATE TRIGGER nook_guest_role BEFORE UPDATE OF role ON oa_operators WHEN NEW.role<>'member' AND EXISTS(SELECT 1 FROM nook_access WHERE user=NEW.id AND mode='guest') BEGIN SELECT RAISE(ABORT,'guest_role_conflict'); END;
CREATE TRIGGER nook_member_admission BEFORE INSERT ON nook_members
BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM nook_access a JOIN oa_operators o ON o.id=a.user WHERE a.user=NEW.user AND a.active=1 AND o.status='active' AND (a.mode='member' OR EXISTS(SELECT 1 FROM nook_guest_grants g WHERE g.user=a.user AND g.conversation=NEW.conversation))) THEN RAISE(ABORT,'product_scope_denied') END; END;
CREATE TRIGGER nook_member_move BEFORE UPDATE ON nook_members BEGIN SELECT RAISE(ABORT,'membership_immutable'); END;
CREATE TRIGGER nook_guest_scope_remove AFTER DELETE ON nook_guest_grants BEGIN DELETE FROM nook_members WHERE user=OLD.user AND conversation=OLD.conversation; END;
CREATE TRIGGER nook_member_scope_remove AFTER DELETE ON nook_members BEGIN DELETE FROM nook_guest_grants WHERE user=OLD.user AND conversation=OLD.conversation; END;
CREATE TRIGGER nook_reaction_admission BEFORE INSERT ON nook_reactions
BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM nook_messages m JOIN nook_members g ON g.conversation=m.conversation JOIN nook_access a ON a.user=g.user JOIN oa_operators o ON o.id=a.user WHERE m.id=NEW.message AND m.deleted=0 AND g.user=NEW.user AND a.active=1 AND o.status='active' AND (a.mode='member' OR EXISTS(SELECT 1 FROM nook_guest_grants scope WHERE scope.user=a.user AND scope.conversation=m.conversation))) THEN RAISE(ABORT,'reaction_scope_denied') END; END;
CREATE TRIGGER nook_recovered_guest_role BEFORE INSERT ON oa_operators WHEN NEW.role<>'member' AND EXISTS(SELECT 1 FROM nook_access WHERE user=NEW.id AND mode='guest') BEGIN SELECT RAISE(ABORT,'guest_role_conflict'); END;
CREATE TRIGGER nook_guest_grant_admission BEFORE INSERT ON nook_guest_grants
BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM nook_access a JOIN nook_conversations c ON c.id=NEW.conversation WHERE a.user=NEW.user AND a.mode='guest' AND a.active=1 AND c.kind<>'dm') THEN RAISE(ABORT,'invalid_guest_scope') END; END;
CREATE TRIGGER nook_conversation_creator BEFORE INSERT ON nook_conversations WHEN (SELECT authority FROM nook_storage WHERE id=1)='normalized'
BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM nook_access a JOIN oa_operators o ON o.id=a.user WHERE a.user=NEW.owner AND a.active=1 AND a.mode='member' AND o.status='active') THEN RAISE(ABORT,'product_scope_denied') END; END;
CREATE TRIGGER nook_reaction_immutable BEFORE UPDATE ON nook_reactions BEGIN SELECT RAISE(ABORT,'reaction_immutable'); END;
CREATE TRIGGER nook_access_role_insert BEFORE INSERT ON nook_access WHEN NEW.mode='guest' AND EXISTS(SELECT 1 FROM oa_operators WHERE id=NEW.user AND role<>'member') BEGIN SELECT RAISE(ABORT,'guest_role_conflict'); END;
CREATE TRIGGER nook_access_role_update BEFORE UPDATE OF mode ON nook_access WHEN NEW.mode='guest' AND EXISTS(SELECT 1 FROM oa_operators WHERE id=NEW.user AND role<>'member') BEGIN SELECT RAISE(ABORT,'guest_role_conflict'); END;
CREATE TRIGGER nook_access_prune AFTER UPDATE OF active,mode ON nook_access
BEGIN
 DELETE FROM nook_members WHERE user=NEW.user AND (NEW.active=0 OR NEW.mode='guest' AND NOT EXISTS(SELECT 1 FROM nook_guest_grants WHERE user=NEW.user AND conversation=nook_members.conversation));
 DELETE FROM nook_guest_grants WHERE user=NEW.user AND (NEW.active=0 OR NEW.mode<>'guest');
END;

-- A creator is historical attribution, not irrevocable private access. Retain
-- the actual revoked membership event and product generation for safe restore.
CREATE TRIGGER nook_creator_revoked AFTER DELETE ON nook_members WHEN EXISTS(SELECT 1 FROM nook_conversations WHERE id=OLD.conversation AND owner=OLD.user)
BEGIN
 UPDATE nook_conversations SET seq=seq+1 WHERE id=OLD.conversation;
 INSERT INTO nook_events SELECT id,seq,'access-revoked',OLD.user,OLD.user FROM nook_conversations WHERE id=OLD.conversation;
 INSERT INTO nook_creator_revocations SELECT c.id,OLD.user,a.generation,c.seq FROM nook_conversations c JOIN nook_access a ON a.user=OLD.user WHERE c.id=OLD.conversation ON CONFLICT(conversation) DO UPDATE SET user=excluded.user,generation=excluded.generation,event_seq=excluded.event_seq;
END;
CREATE TRIGGER nook_creator_readmitted AFTER INSERT ON nook_members WHEN EXISTS(SELECT 1 FROM nook_conversations WHERE id=NEW.conversation AND owner=NEW.user)
BEGIN DELETE FROM nook_creator_revocations WHERE conversation=NEW.conversation AND user=NEW.user; END;

DELETE FROM nook_members WHERE NOT EXISTS(SELECT 1 FROM nook_access a JOIN oa_operators o ON o.id=a.user WHERE a.user=nook_members.user AND a.active=1 AND o.status='active');

-- Actual Base import-kit D1 schema; product-owned additive migration.
CREATE TABLE IF NOT EXISTS ik_jobs (
 id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL,
 mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, fingerprint TEXT NOT NULL,
 operation_key TEXT NOT NULL, plan_json TEXT NOT NULL, state TEXT NOT NULL,
 checkpoint INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL, fence INTEGER NOT NULL DEFAULT 0,
 lease_token TEXT, lease_expires INTEGER, error TEXT,
 UNIQUE(destination, principal_id, operation_key)
);
CREATE TABLE IF NOT EXISTS ik_original_sets (
 job_id TEXT PRIMARY KEY REFERENCES ik_jobs(id), version INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ik_originals (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id), kind TEXT NOT NULL, original_key TEXT NOT NULL,
 name TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, bytes BLOB,
 PRIMARY KEY(job_id,kind,original_key)
);
CREATE TABLE IF NOT EXISTS ik_sources (
 identity TEXT PRIMARY KEY, source_hash TEXT NOT NULL, mapping_version TEXT NOT NULL,
 effects_hash TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES ik_jobs(id)
);
CREATE TABLE IF NOT EXISTS ik_provenance (
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, effect_ordinal INTEGER NOT NULL,
 source_identity TEXT NOT NULL, destination TEXT NOT NULL, target_kind TEXT NOT NULL,
 target_id TEXT NOT NULL, reversed INTEGER NOT NULL DEFAULT 0, record_json TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS ik_active_target ON ik_provenance(destination,target_kind,target_id) WHERE reversed=0;
CREATE TABLE IF NOT EXISTS ik_stages (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id), fence INTEGER NOT NULL, effect_id TEXT NOT NULL,
 sha256 TEXT NOT NULL, bytes BLOB NOT NULL, PRIMARY KEY(job_id,fence,effect_id)
);
CREATE TABLE IF NOT EXISTS ik_batches (
 job_id TEXT NOT NULL REFERENCES ik_jobs(id), action TEXT NOT NULL, position INTEGER NOT NULL,
 end_position INTEGER NOT NULL, fence INTEGER NOT NULL, PRIMARY KEY(job_id,action,position)
);
CREATE TABLE IF NOT EXISTS ik_targets (
 destination TEXT NOT NULL, kind TEXT NOT NULL, id TEXT NOT NULL,
 revision TEXT NOT NULL, value_json TEXT NOT NULL, attachment_json TEXT,
 PRIMARY KEY(destination,kind,id)
);
CREATE TABLE IF NOT EXISTS ik_d1_plan_chunks (job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, body TEXT NOT NULL, PRIMARY KEY(job_id,ordinal));
CREATE TABLE IF NOT EXISTS ik_d1_original_chunks (job_id TEXT NOT NULL REFERENCES ik_jobs(id), kind TEXT NOT NULL, original_key TEXT NOT NULL, ordinal INTEGER NOT NULL, bytes BLOB NOT NULL, PRIMARY KEY(job_id,kind,original_key,ordinal));
CREATE TABLE IF NOT EXISTS ik_d1_history (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, effect_ordinal INTEGER NOT NULL, source_identity TEXT NOT NULL, destination TEXT NOT NULL, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, reversed INTEGER NOT NULL CHECK(reversed=0), record_json TEXT NOT NULL, successor_id TEXT NOT NULL UNIQUE);
CREATE INDEX IF NOT EXISTS ik_d1_history_job ON ik_d1_history(job_id);
CREATE TABLE IF NOT EXISTS ik_d1_entries (job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, source_identity TEXT NOT NULL, owner_job_id TEXT NOT NULL REFERENCES ik_jobs(id), effects_hash TEXT NOT NULL, PRIMARY KEY(job_id,ordinal));
CREATE TABLE IF NOT EXISTS ik_d1_assertions (ok INTEGER NOT NULL CONSTRAINT IMPORT_ATOMIC_GUARD CHECK(ok=1));
ALTER TABLE ik_jobs ADD COLUMN reversal_policy TEXT NOT NULL DEFAULT 'strict' CHECK(reversal_policy IN ('strict','preserve-conflicts'));
ALTER TABLE ik_jobs ADD COLUMN reversal_policy_hash TEXT;
ALTER TABLE ik_jobs ADD COLUMN reversal_cursor INTEGER NOT NULL DEFAULT 0 CHECK(reversal_cursor>=0);
ALTER TABLE ik_jobs ADD COLUMN reversal_hash TEXT NOT NULL DEFAULT '4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945';
CREATE TABLE ik_d1_creation_plans (job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, body TEXT NOT NULL, released INTEGER NOT NULL DEFAULT 0 CHECK(released IN (0,1)), PRIMARY KEY(job_id,ordinal));
CREATE TRIGGER ik_d1_creation_plan_capture AFTER INSERT ON ik_d1_plan_chunks BEGIN INSERT INTO ik_d1_creation_plans(job_id,ordinal,body) VALUES(NEW.job_id,NEW.ordinal,NEW.body); END;
CREATE TRIGGER ik_d1_creation_plan_immutable BEFORE UPDATE ON ik_d1_creation_plans WHEN NEW.job_id IS NOT OLD.job_id OR NEW.ordinal IS NOT OLD.ordinal OR NEW.body IS NOT OLD.body OR OLD.released<>0 OR NEW.released<>1 OR NOT EXISTS(SELECT 1 FROM ik_d1_plan_chunks p WHERE p.job_id=OLD.job_id AND p.ordinal=OLD.ordinal AND p.body IS OLD.body) BEGIN SELECT RAISE(ABORT,'IMPORT_CREATION_SNAPSHOT_CHANGED'); END;
CREATE TRIGGER ik_d1_creation_plan_release BEFORE DELETE ON ik_d1_creation_plans WHEN OLD.released<>1 BEGIN SELECT RAISE(ABORT,'IMPORT_CREATION_SNAPSHOT_CHANGED'); END;
CREATE TABLE ik_d1_reversal_reports (job_id TEXT NOT NULL REFERENCES ik_jobs(id), effect_id TEXT NOT NULL, position INTEGER NOT NULL, record_json TEXT NOT NULL, PRIMARY KEY(job_id,effect_id), UNIQUE(job_id,position));
CREATE TABLE IF NOT EXISTS ik_d1_streams (id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL, mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, fingerprint TEXT NOT NULL, operation_key TEXT NOT NULL, total INTEGER NOT NULL, layout_hash TEXT NOT NULL, state TEXT NOT NULL, UNIQUE(destination,principal_id,operation_key));
CREATE TABLE IF NOT EXISTS ik_d1_stream_pages (stream_id TEXT NOT NULL REFERENCES ik_d1_streams(id), ordinal INTEGER NOT NULL, job_id TEXT NOT NULL UNIQUE REFERENCES ik_jobs(id), total INTEGER NOT NULL, erased_records INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(stream_id,ordinal));
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_page_delete AFTER DELETE ON ik_d1_stream_pages BEGIN UPDATE ik_d1_streams SET state='invalid' WHERE id=OLD.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_page_update AFTER UPDATE OF stream_id,ordinal,job_id,total ON ik_d1_stream_pages BEGIN UPDATE ik_d1_streams SET state='invalid' WHERE id=OLD.stream_id OR id=NEW.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_page_insert AFTER INSERT ON ik_d1_stream_pages BEGIN UPDATE ik_d1_streams SET state='invalid' WHERE id=NEW.stream_id; END;
CREATE TABLE IF NOT EXISTS ik_d1_erased_sources (destination TEXT NOT NULL, identity TEXT NOT NULL, PRIMARY KEY(destination,identity));
CREATE TABLE IF NOT EXISTS ik_d1_erased_targets (destination TEXT NOT NULL, identity TEXT NOT NULL, PRIMARY KEY(destination,identity));
CREATE TABLE IF NOT EXISTS ik_d1_indexed_jobs (job_id TEXT PRIMARY KEY REFERENCES ik_jobs(id), fingerprint TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ik_d1_plan_index (job_id TEXT NOT NULL REFERENCES ik_jobs(id), ordinal INTEGER NOT NULL, source_identity TEXT NOT NULL, target_identity TEXT NOT NULL, PRIMARY KEY(job_id,ordinal,target_identity));
CREATE INDEX IF NOT EXISTS ik_d1_plan_index_source ON ik_d1_plan_index(source_identity,job_id);
CREATE INDEX IF NOT EXISTS ik_d1_plan_index_target ON ik_d1_plan_index(target_identity,job_id);
CREATE TRIGGER IF NOT EXISTS ik_d1_plan_index_insert AFTER INSERT ON ik_d1_plan_index BEGIN DELETE FROM ik_d1_indexed_jobs WHERE job_id=NEW.job_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_plan_index_delete AFTER DELETE ON ik_d1_plan_index BEGIN DELETE FROM ik_d1_indexed_jobs WHERE job_id=OLD.job_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_plan_index_update AFTER UPDATE ON ik_d1_plan_index BEGIN DELETE FROM ik_d1_indexed_jobs WHERE job_id=OLD.job_id OR job_id=NEW.job_id; END;
CREATE TABLE IF NOT EXISTS ik_d1_stream_origins (job_id TEXT PRIMARY KEY,stream_id TEXT NOT NULL,ordinal INTEGER NOT NULL,page_total INTEGER NOT NULL,job_operation_key TEXT NOT NULL,parent_destination TEXT NOT NULL,parent_namespace TEXT NOT NULL,parent_mapping_version TEXT NOT NULL,parent_principal_id TEXT NOT NULL,parent_fingerprint TEXT NOT NULL,parent_operation_key TEXT NOT NULL,parent_total INTEGER NOT NULL,parent_layout_hash TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ik_d1_stream_origin_parent ON ik_d1_stream_origins(stream_id,ordinal);
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_origin_insert BEFORE INSERT ON ik_d1_stream_origins WHEN EXISTS(SELECT 1 FROM ik_d1_stream_origins WHERE job_id=NEW.job_id) OR NOT EXISTS(SELECT 1 FROM ik_d1_stream_pages p JOIN ik_d1_streams s ON s.id=p.stream_id JOIN ik_jobs j ON j.id=p.job_id WHERE ((((NEW.job_id IS p.job_id AND NEW.stream_id IS s.id) AND (NEW.ordinal IS p.ordinal AND NEW.page_total IS p.total)) AND ((NEW.job_operation_key IS j.operation_key AND NEW.parent_destination IS s.destination) AND (NEW.parent_namespace IS s.namespace AND (NEW.parent_mapping_version IS s.mapping_version AND NEW.parent_principal_id IS s.principal_id)))) AND (((NEW.parent_fingerprint IS s.fingerprint AND NEW.parent_operation_key IS s.operation_key) AND (NEW.parent_total IS s.total AND (NEW.parent_layout_hash IS s.layout_hash AND p.stream_id IS s.id))) AND ((j.total IS p.total AND j.destination IS s.destination) AND (j.namespace IS s.namespace AND (j.mapping_version IS s.mapping_version AND j.principal_id IS s.principal_id)))))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_ORIGIN_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_origin_update BEFORE UPDATE ON ik_d1_stream_origins BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_ORIGIN_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_origin_delete BEFORE DELETE ON ik_d1_stream_origins WHEN EXISTS(SELECT 1 FROM ik_jobs WHERE id=OLD.job_id) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_ORIGIN_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_origin_job_delete AFTER DELETE ON ik_jobs BEGIN DELETE FROM ik_d1_stream_origins WHERE job_id=OLD.id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_origin_page_insert AFTER INSERT ON ik_d1_stream_pages BEGIN INSERT INTO ik_d1_stream_origins(job_id,stream_id,ordinal,page_total,job_operation_key,parent_destination,parent_namespace,parent_mapping_version,parent_principal_id,parent_fingerprint,parent_operation_key,parent_total,parent_layout_hash) SELECT p.job_id,s.id,p.ordinal,p.total,j.operation_key,s.destination,s.namespace,s.mapping_version,s.principal_id,s.fingerprint,s.operation_key,s.total,s.layout_hash FROM ik_d1_stream_pages p JOIN ik_d1_streams s ON s.id=p.stream_id JOIN ik_jobs j ON j.id=p.job_id WHERE NOT EXISTS(SELECT 1 FROM ik_d1_stream_origins o WHERE o.job_id=p.job_id) AND j.total IS p.total AND j.destination IS s.destination AND j.namespace IS s.namespace AND j.mapping_version IS s.mapping_version AND j.principal_id IS s.principal_id AND p.job_id=NEW.job_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_origin_page_update AFTER UPDATE OF stream_id,ordinal,job_id,total ON ik_d1_stream_pages BEGIN INSERT INTO ik_d1_stream_origins(job_id,stream_id,ordinal,page_total,job_operation_key,parent_destination,parent_namespace,parent_mapping_version,parent_principal_id,parent_fingerprint,parent_operation_key,parent_total,parent_layout_hash) SELECT p.job_id,s.id,p.ordinal,p.total,j.operation_key,s.destination,s.namespace,s.mapping_version,s.principal_id,s.fingerprint,s.operation_key,s.total,s.layout_hash FROM ik_d1_stream_pages p JOIN ik_d1_streams s ON s.id=p.stream_id JOIN ik_jobs j ON j.id=p.job_id WHERE NOT EXISTS(SELECT 1 FROM ik_d1_stream_origins o WHERE o.job_id=p.job_id) AND j.total IS p.total AND j.destination IS s.destination AND j.namespace IS s.namespace AND j.mapping_version IS s.mapping_version AND j.principal_id IS s.principal_id AND p.job_id=NEW.job_id; END;
INSERT INTO ik_d1_stream_origins(job_id,stream_id,ordinal,page_total,job_operation_key,parent_destination,parent_namespace,parent_mapping_version,parent_principal_id,parent_fingerprint,parent_operation_key,parent_total,parent_layout_hash) SELECT p.job_id,s.id,p.ordinal,p.total,j.operation_key,s.destination,s.namespace,s.mapping_version,s.principal_id,s.fingerprint,s.operation_key,s.total,s.layout_hash FROM ik_d1_stream_pages p JOIN ik_d1_streams s ON s.id=p.stream_id JOIN ik_jobs j ON j.id=p.job_id WHERE NOT EXISTS(SELECT 1 FROM ik_d1_stream_origins o WHERE o.job_id=p.job_id) AND j.total IS p.total AND j.destination IS s.destination AND j.namespace IS s.namespace AND j.mapping_version IS s.mapping_version AND j.principal_id IS s.principal_id;
CREATE TABLE IF NOT EXISTS ik_d1_stream_revisions(stream_id TEXT PRIMARY KEY,destination TEXT NOT NULL,namespace TEXT NOT NULL,mapping_version TEXT NOT NULL,principal_id TEXT NOT NULL,fingerprint TEXT NOT NULL,operation_key TEXT NOT NULL,total INTEGER NOT NULL,layout_hash TEXT NOT NULL,layout_revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(layout_revision)='integer' AND layout_revision>=0),progress_revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(progress_revision)='integer' AND progress_revision>=0));
INSERT INTO ik_d1_stream_revisions(stream_id,destination,namespace,mapping_version,principal_id,fingerprint,operation_key,total,layout_hash) SELECT id,destination,namespace,mapping_version,principal_id,fingerprint,operation_key,total,layout_hash FROM ik_d1_streams WHERE NOT EXISTS(SELECT 1 FROM ik_d1_stream_revisions WHERE stream_id=ik_d1_streams.id);
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_insert BEFORE INSERT ON ik_d1_stream_revisions WHEN EXISTS(SELECT 1 FROM ik_d1_stream_revisions WHERE stream_id=NEW.stream_id) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.namespace IS NOT OLD.namespace OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.operation_key IS NOT OLD.operation_key OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_delete BEFORE DELETE ON ik_d1_stream_revisions BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_parent_insert AFTER INSERT ON ik_d1_streams BEGIN INSERT INTO ik_d1_stream_revisions(stream_id,destination,namespace,mapping_version,principal_id,fingerprint,operation_key,total,layout_hash) SELECT NEW.id,NEW.destination,NEW.namespace,NEW.mapping_version,NEW.principal_id,NEW.fingerprint,NEW.operation_key,NEW.total,NEW.layout_hash WHERE NOT EXISTS(SELECT 1 FROM ik_d1_stream_revisions WHERE stream_id=NEW.id); UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_parent_delete AFTER DELETE ON ik_d1_streams BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=OLD.id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_parent_update AFTER UPDATE ON ik_d1_streams BEGIN UPDATE ik_d1_stream_revisions SET progress_revision=progress_revision+1 WHERE stream_id=OLD.id OR stream_id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_parent_layout AFTER UPDATE OF id,destination,namespace,mapping_version,principal_id,fingerprint,operation_key,total,layout_hash ON ik_d1_streams BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=OLD.id OR stream_id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_ik_d1_stream_pages_insert AFTER INSERT ON ik_d1_stream_pages BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=NEW.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_ik_d1_stream_pages_update AFTER UPDATE OF stream_id,ordinal,job_id,total ON ik_d1_stream_pages BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=OLD.stream_id OR stream_id=NEW.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_ik_d1_stream_pages_delete AFTER DELETE ON ik_d1_stream_pages BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=OLD.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_ik_d1_stream_origins_insert AFTER INSERT ON ik_d1_stream_origins BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=NEW.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_ik_d1_stream_origins_update AFTER UPDATE ON ik_d1_stream_origins BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=OLD.stream_id OR stream_id=NEW.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_ik_d1_stream_origins_delete AFTER DELETE ON ik_d1_stream_origins BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id=OLD.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_page_erasure AFTER UPDATE OF erased_records ON ik_d1_stream_pages BEGIN UPDATE ik_d1_stream_revisions SET progress_revision=progress_revision+1 WHERE stream_id=OLD.stream_id OR stream_id=NEW.stream_id; END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_job_insert AFTER INSERT ON ik_jobs BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id IN (SELECT stream_id FROM ik_d1_stream_pages WHERE job_id=NEW.id UNION SELECT stream_id FROM ik_d1_stream_origins WHERE job_id=NEW.id); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_job_update AFTER UPDATE ON ik_jobs BEGIN UPDATE ik_d1_stream_revisions SET progress_revision=progress_revision+1 WHERE stream_id IN (SELECT stream_id FROM ik_d1_stream_pages WHERE job_id=OLD.id OR job_id=NEW.id UNION SELECT stream_id FROM ik_d1_stream_origins WHERE job_id=OLD.id OR job_id=NEW.id); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_job_delete AFTER DELETE ON ik_jobs BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id IN (SELECT stream_id FROM ik_d1_stream_pages WHERE job_id=OLD.id UNION SELECT stream_id FROM ik_d1_stream_origins WHERE job_id=OLD.id); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_stream_revision_job_layout AFTER UPDATE OF id,destination,namespace,mapping_version,principal_id,fingerprint,operation_key,total,reversal_policy,reversal_policy_hash ON ik_jobs BEGIN UPDATE ik_d1_stream_revisions SET layout_revision=layout_revision+1,progress_revision=progress_revision+1 WHERE stream_id IN (SELECT stream_id FROM ik_d1_stream_pages WHERE job_id=OLD.id OR job_id=NEW.id UNION SELECT stream_id FROM ik_d1_stream_origins WHERE job_id=OLD.id OR job_id=NEW.id); END;
INSERT INTO ik_d1_assertions(ok) SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM ik_jobs legacy WHERE (EXISTS(SELECT 1 FROM ik_original_sets os WHERE os.job_id=legacy.id AND os.version=4) OR EXISTS(SELECT 1 FROM ik_d1_stream_origins oo WHERE oo.job_id=legacy.id) OR EXISTS(SELECT 1 FROM ik_d1_stream_pages op WHERE op.job_id=legacy.id)) AND NOT EXISTS(SELECT 1 FROM ik_d1_stream_origins o JOIN ik_d1_stream_pages p ON p.job_id=o.job_id JOIN ik_d1_streams s ON s.id=o.stream_id JOIN ik_jobs j ON j.id=o.job_id WHERE o.job_id=legacy.id AND ((((o.job_id IS p.job_id AND o.stream_id IS s.id) AND (o.ordinal IS p.ordinal AND o.page_total IS p.total)) AND ((o.job_operation_key IS j.operation_key AND o.parent_destination IS s.destination) AND (o.parent_namespace IS s.namespace AND (o.parent_mapping_version IS s.mapping_version AND o.parent_principal_id IS s.principal_id)))) AND (((o.parent_fingerprint IS s.fingerprint AND o.parent_operation_key IS s.operation_key) AND (o.parent_total IS s.total AND (o.parent_layout_hash IS s.layout_hash AND p.stream_id IS s.id))) AND ((j.total IS p.total AND j.destination IS s.destination) AND (j.namespace IS s.namespace AND (j.mapping_version IS s.mapping_version AND j.principal_id IS s.principal_id))))) AND s.state IN ('applying','undoing') AND EXISTS(SELECT 1 FROM ik_d1_stream_revisions sr WHERE sr.stream_id=s.id AND s.destination IS sr.destination AND s.namespace IS sr.namespace AND s.mapping_version IS sr.mapping_version AND s.principal_id IS sr.principal_id AND s.fingerprint IS sr.fingerprint AND s.operation_key IS sr.operation_key AND s.total IS sr.total AND s.layout_hash IS sr.layout_hash) AND NOT EXISTS(SELECT 1 FROM ik_d1_stream_pages op WHERE op.stream_id=s.id AND NOT EXISTS(SELECT 1 FROM ik_d1_stream_origins oo JOIN ik_jobs oj ON oj.id=oo.job_id WHERE ((((oo.job_id IS op.job_id AND oo.stream_id IS s.id) AND (oo.ordinal IS op.ordinal AND oo.page_total IS op.total)) AND ((oo.job_operation_key IS oj.operation_key AND oo.parent_destination IS s.destination) AND (oo.parent_namespace IS s.namespace AND (oo.parent_mapping_version IS s.mapping_version AND oo.parent_principal_id IS s.principal_id)))) AND (((oo.parent_fingerprint IS s.fingerprint AND oo.parent_operation_key IS s.operation_key) AND (oo.parent_total IS s.total AND (oo.parent_layout_hash IS s.layout_hash AND op.stream_id IS s.id))) AND ((oj.total IS op.total AND oj.destination IS s.destination) AND (oj.namespace IS s.namespace AND (oj.mapping_version IS s.mapping_version AND oj.principal_id IS s.principal_id))))))) AND NOT EXISTS(SELECT 1 FROM ik_d1_stream_origins oo WHERE oo.stream_id=s.id AND NOT EXISTS(SELECT 1 FROM ik_d1_stream_pages op JOIN ik_jobs oj ON oj.id=op.job_id WHERE ((((oo.job_id IS op.job_id AND oo.stream_id IS s.id) AND (oo.ordinal IS op.ordinal AND oo.page_total IS op.total)) AND ((oo.job_operation_key IS oj.operation_key AND oo.parent_destination IS s.destination) AND (oo.parent_namespace IS s.namespace AND (oo.parent_mapping_version IS s.mapping_version AND oo.parent_principal_id IS s.principal_id)))) AND (((oo.parent_fingerprint IS s.fingerprint AND oo.parent_operation_key IS s.operation_key) AND (oo.parent_total IS s.total AND (oo.parent_layout_hash IS s.layout_hash AND op.stream_id IS s.id))) AND ((oj.total IS op.total AND oj.destination IS s.destination) AND (oj.namespace IS s.namespace AND (oj.mapping_version IS s.mapping_version AND oj.principal_id IS s.principal_id))))))))) THEN 1 ELSE 0 END;
UPDATE ik_original_sets SET version=4 WHERE version=3 AND job_id IN (SELECT job_id FROM ik_d1_stream_pages);
DELETE FROM ik_d1_assertions;
CREATE TABLE IF NOT EXISTS ik_d1_publication_fences (stream_id TEXT NOT NULL,job_id TEXT PRIMARY KEY);
CREATE INDEX IF NOT EXISTS ik_d1_publication_fence_stream ON ik_d1_publication_fences(stream_id);
CREATE TRIGGER IF NOT EXISTS ik_d1_publication_ik_jobs_insert BEFORE INSERT ON ik_jobs WHEN EXISTS(SELECT 1 FROM ik_d1_publication_fences WHERE job_id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_PUBLICATION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_publication_ik_jobs_update BEFORE UPDATE ON ik_jobs WHEN EXISTS(SELECT 1 FROM ik_d1_publication_fences WHERE job_id=OLD.id OR job_id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_PUBLICATION_CHANGED'); END;
