CREATE TRIGGER nook_attachments_inventory_update AFTER UPDATE ON nook_attachments BEGIN DELETE FROM nook_object_inventory WHERE object_key=OLD.object_key AND NOT EXISTS(SELECT 1 FROM nook_attachments WHERE object_key=OLD.object_key) AND NOT EXISTS(SELECT 1 FROM nook_import_uploads WHERE object_key=OLD.object_key AND state='ready') AND NOT EXISTS(SELECT 1 FROM nook_import_objects WHERE object_key=OLD.object_key AND state='ready'); INSERT OR IGNORE INTO nook_object_inventory SELECT NEW.object_key WHERE NEW.object_key IS NOT NULL; END;
CREATE TRIGGER nook_attachments_inventory_delete AFTER DELETE ON nook_attachments BEGIN DELETE FROM nook_object_inventory WHERE object_key=OLD.object_key AND NOT EXISTS(SELECT 1 FROM nook_attachments WHERE object_key=OLD.object_key) AND NOT EXISTS(SELECT 1 FROM nook_import_uploads WHERE object_key=OLD.object_key AND state='ready') AND NOT EXISTS(SELECT 1 FROM nook_import_objects WHERE object_key=OLD.object_key AND state='ready'); END;
CREATE TRIGGER nook_import_uploads_inventory_insert AFTER INSERT ON nook_import_uploads WHEN NEW.state='ready' BEGIN INSERT OR IGNORE INTO nook_object_inventory VALUES(NEW.object_key); END;
