CREATE TRIGGER nook_import_uploads_inventory_delete AFTER DELETE ON nook_import_uploads BEGIN DELETE FROM nook_object_inventory WHERE object_key=OLD.object_key AND NOT EXISTS(SELECT 1 FROM nook_attachments WHERE object_key=OLD.object_key) AND NOT EXISTS(SELECT 1 FROM nook_import_uploads WHERE object_key=OLD.object_key AND state='ready') AND NOT EXISTS(SELECT 1 FROM nook_import_objects WHERE object_key=OLD.object_key AND state='ready'); END;
