ALTER TABLE nook_notify_preferences ADD COLUMN mobile_delay_minutes INTEGER NOT NULL DEFAULT 0 CHECK(mobile_delay_minutes IN (0,1,2,5,10,15,30));
ALTER TABLE nook_notify_queue ADD COLUMN held_at INTEGER;
ALTER TABLE nook_notify_queue ADD COLUMN active_until INTEGER;
ALTER TABLE nook_notify_queue ADD COLUMN released_at INTEGER;
ALTER TABLE nook_push_presence ADD COLUMN device_class TEXT NOT NULL DEFAULT 'desktop' CHECK(device_class IN ('desktop','mobile'));

DROP TRIGGER nook_push_read_insert;
DROP TRIGGER nook_push_read_update;
DROP TRIGGER nook_push_done;
CREATE TRIGGER nook_push_read_insert AFTER INSERT ON nook_reads BEGIN
 UPDATE nook_notify_queue SET state='cancelled',error=CASE WHEN held_at IS NOT NULL THEN 'held-active-elsewhere' ELSE 'seen' END,updated=CAST(unixepoch('subsec')*1000 AS INTEGER) WHERE channel='push' AND user=NEW.user AND conversation=NEW.conversation AND message IS NOT NULL AND event_seq<=NEW.seq AND state IN ('pending','retrying');
END;
CREATE TRIGGER nook_push_read_update AFTER UPDATE OF seq ON nook_reads BEGIN
 UPDATE nook_notify_queue SET state='cancelled',error=CASE WHEN held_at IS NOT NULL THEN 'held-active-elsewhere' ELSE 'seen' END,updated=CAST(unixepoch('subsec')*1000 AS INTEGER) WHERE channel='push' AND user=NEW.user AND conversation=NEW.conversation AND message IS NOT NULL AND event_seq<=NEW.seq AND state IN ('pending','retrying');
END;
CREATE TRIGGER nook_push_done AFTER UPDATE OF state ON nook_attention WHEN NEW.state='done' BEGIN
 UPDATE nook_notify_queue SET state='cancelled',error=CASE WHEN held_at IS NOT NULL THEN 'held-active-elsewhere' ELSE 'seen' END,updated=CAST(unixepoch('subsec')*1000 AS INTEGER) WHERE channel='push' AND attention=NEW.id AND state IN ('pending','retrying');
END;

-- Conversation-local notes. Checklist state never confers outcome authority.
CREATE TABLE nook_notes (
 id TEXT PRIMARY KEY,
 conversation TEXT NOT NULL REFERENCES nook_conversations(id),
 thread TEXT,
 author TEXT,
 created TEXT NOT NULL,
 updated TEXT NOT NULL,
 version INTEGER NOT NULL CHECK(version>0),
 title TEXT NOT NULL,
 body TEXT NOT NULL,
 items_json TEXT NOT NULL CHECK(json_valid(items_json)),
 links_json TEXT NOT NULL CHECK(json_valid(links_json)),
 pinned INTEGER NOT NULL CHECK(pinned IN (0,1)),
 pinned_by TEXT,
 pinned_at TEXT,
 deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1))
);
CREATE INDEX nook_notes_scope ON nook_notes(conversation,thread,id);
CREATE INDEX nook_notes_author ON nook_notes(author,id);
CREATE TABLE nook_note_versions (
 note TEXT NOT NULL REFERENCES nook_notes(id),
 version INTEGER NOT NULL CHECK(version>0),
 actor TEXT,
 created TEXT NOT NULL,
 title TEXT NOT NULL,
 body TEXT NOT NULL,
 items_json TEXT NOT NULL CHECK(json_valid(items_json)),
 links_json TEXT NOT NULL CHECK(json_valid(links_json)),
 pinned INTEGER NOT NULL CHECK(pinned IN (0,1)),
 pinned_by TEXT,
 pinned_at TEXT,
 deleted INTEGER NOT NULL CHECK(deleted IN (0,1)),
 reverted_from INTEGER,
 PRIMARY KEY(note,version)
);
CREATE INDEX nook_note_version_actor ON nook_note_versions(actor,note);
CREATE TABLE nook_note_proposals (
 outcome TEXT PRIMARY KEY REFERENCES nook_outcomes(id),
 note TEXT NOT NULL REFERENCES nook_notes(id),
 item TEXT NOT NULL,
 note_version INTEGER NOT NULL,
 created TEXT NOT NULL,
 UNIQUE(note,item,note_version),
 FOREIGN KEY(note,note_version) REFERENCES nook_note_versions(note,version)
);

CREATE TRIGGER nook_exit_change_nook_notes_insert AFTER INSERT ON nook_notes BEGIN INSERT INTO nook_exit_changes(conversation,revision) SELECT NEW.conversation,1 WHERE NEW.conversation IS NOT NULL ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER nook_exit_change_nook_notes_update AFTER UPDATE ON nook_notes BEGIN INSERT INTO nook_exit_changes(conversation,revision) SELECT NEW.conversation,1 WHERE NEW.conversation IS NOT NULL ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;

