-- NOOK-080: an approval is one app identity in one explicitly named channel.
-- App actors have no operator account, mailbox, session or human admission.
CREATE TABLE nook_notification_apps(
 id TEXT PRIMARY KEY,name TEXT NOT NULL,conversation TEXT NOT NULL,
 creator TEXT,created INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','revoked','removed','reissue')),ended INTEGER
);
CREATE UNIQUE INDEX nook_notification_active_name ON nook_notification_apps(name,conversation) WHERE state='active';
CREATE INDEX nook_notification_app_channel ON nook_notification_apps(conversation,state);
CREATE TABLE nook_notification_secrets(app TEXT PRIMARY KEY,hash TEXT NOT NULL);
CREATE TABLE nook_notification_rates(conversation TEXT PRIMARY KEY,balance INTEGER NOT NULL,updated INTEGER NOT NULL);
-- Unknown/changed federation is fail closed. Today's product has no shared-channel door.
CREATE TABLE nook_notification_sharing(conversation TEXT PRIMARY KEY,state TEXT NOT NULL CHECK(state IN ('local','shared','unknown')));
CREATE TRIGGER nook_notification_actor AFTER INSERT ON nook_notification_apps BEGIN
 INSERT OR IGNORE INTO nook_actors(id,name,email,role,active) VALUES(NEW.id,NEW.name,NULL,'app',0);
END;
-- Existing accounts have no historical address-bound proof to invent. A fresh
-- native confirmation establishes the exact mailbox; changing it clears proof.
CREATE TABLE nook_notification_email_facts(user TEXT PRIMARY KEY,email TEXT NOT NULL,verified_at INTEGER NOT NULL);
CREATE TRIGGER nook_notification_email_confirmed AFTER INSERT ON oa_sessions
 WHEN NEW.kind='native' AND NEW.source_token_id IS NOT NULL
BEGIN
 INSERT INTO nook_notification_email_facts SELECT NEW.operator_id,email,NEW.created_at FROM oa_operators WHERE id=NEW.operator_id
 ON CONFLICT(user) DO UPDATE SET email=excluded.email,verified_at=excluded.verified_at;
END;
CREATE TRIGGER nook_notification_email_changed AFTER UPDATE OF email ON oa_operators
 WHEN OLD.email<>NEW.email BEGIN DELETE FROM nook_notification_email_facts WHERE user=NEW.id; END;
CREATE TRIGGER nook_notification_exit_insert AFTER INSERT ON nook_notification_apps BEGIN INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_notification_exit_update AFTER UPDATE ON nook_notification_apps BEGIN INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_notification_exit_delete AFTER DELETE ON nook_notification_apps BEGIN INSERT INTO nook_exit_changes VALUES(OLD.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;

-- NOOK-036: settings are portable only while off; credentials and cost counters are not.
CREATE TABLE nook_ai_settings(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),model TEXT NOT NULL,base_url TEXT NOT NULL,daily_cap INTEGER NOT NULL CHECK(daily_cap BETWEEN 1 AND 1000),version INTEGER NOT NULL);
CREATE TABLE nook_ai_secrets(id INTEGER PRIMARY KEY CHECK(id=1),sealed TEXT NOT NULL);
CREATE TABLE nook_ai_calls(day TEXT PRIMARY KEY,calls INTEGER NOT NULL);
CREATE TABLE nook_ai_feedback(id TEXT PRIMARY KEY,user TEXT NOT NULL,conversation TEXT NOT NULL,message TEXT NOT NULL,correction TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TRIGGER nook_ai_feedback_message AFTER DELETE ON nook_messages BEGIN DELETE FROM nook_ai_feedback WHERE message=OLD.id; END;
CREATE TRIGGER nook_ai_feedback_import AFTER DELETE ON nook_import_records BEGIN DELETE FROM nook_ai_feedback WHERE message=OLD.id; END;
CREATE TRIGGER nook_ai_feedback_exit_insert AFTER INSERT ON nook_ai_feedback BEGIN INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_ai_feedback_exit_delete AFTER DELETE ON nook_ai_feedback BEGIN INSERT INTO nook_exit_changes VALUES(OLD.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;

-- Recaps persist only member feedback, never generated answers or credentials.
CREATE TABLE nook_recap_feedback(id TEXT PRIMARY KEY,user TEXT NOT NULL,conversation TEXT NOT NULL,message TEXT NOT NULL,recap TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('correction','dismissal')),correction TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TRIGGER nook_recap_feedback_message AFTER DELETE ON nook_messages BEGIN DELETE FROM nook_recap_feedback WHERE message=OLD.id; END;
CREATE TRIGGER nook_recap_feedback_import AFTER DELETE ON nook_import_records BEGIN DELETE FROM nook_recap_feedback WHERE message=OLD.id; END;
CREATE TRIGGER nook_recap_feedback_exit_insert AFTER INSERT ON nook_recap_feedback BEGIN INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_recap_feedback_exit_delete AFTER DELETE ON nook_recap_feedback BEGIN INSERT INTO nook_exit_changes VALUES(OLD.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;

-- A forward grants a shown snapshot or a link, never source conversation access.
CREATE TABLE nook_forward_policy(id INTEGER PRIMARY KEY CHECK(id=1),mode TEXT NOT NULL CHECK(mode IN ('allow','link-only','blocked')),version INTEGER NOT NULL);
CREATE TABLE nook_forwards(message TEXT PRIMARY KEY,conversation TEXT NOT NULL,source TEXT NOT NULL,source_conversation TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('link','show')),note TEXT NOT NULL,intent TEXT NOT NULL,request_hash TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX nook_forward_source ON nook_forwards(source);
CREATE TABLE nook_forward_files(attachment TEXT PRIMARY KEY,source_attachment TEXT NOT NULL,message TEXT NOT NULL,conversation TEXT NOT NULL);
CREATE INDEX nook_forward_file_source ON nook_forward_files(source_attachment);
CREATE TRIGGER nook_forward_exit_insert AFTER INSERT ON nook_forwards BEGIN INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_forward_exit_delete AFTER DELETE ON nook_forwards BEGIN INSERT INTO nook_exit_changes VALUES(OLD.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
-- A body-free replay event refreshes every descendant copy after a source edit.
CREATE TRIGGER nook_forward_edit AFTER UPDATE OF body ON nook_messages WHEN NEW.body<>OLD.body BEGIN
 UPDATE nook_conversations SET seq=seq+1 WHERE id IN (WITH RECURSIVE copies(message,conversation) AS (SELECT message,conversation FROM nook_forwards WHERE source=NEW.id UNION SELECT f.message,f.conversation FROM nook_forwards f JOIN copies c ON f.source=c.message) SELECT conversation FROM copies);
 INSERT INTO nook_events SELECT c.id,c.seq,'edit',(SELECT min(f.message) FROM nook_forwards f WHERE f.conversation=c.id),NULL FROM nook_conversations c WHERE c.id IN (WITH RECURSIVE copies(message,conversation) AS (SELECT message,conversation FROM nook_forwards WHERE source=NEW.id UNION SELECT f.message,f.conversation FROM nook_forwards f JOIN copies c ON f.source=c.message) SELECT conversation FROM copies);
END;

-- A clip reuses its native attachment bytes and source-message audience.
-- Only transcript corrections create rows. No provider state or retention grant.
CREATE TABLE nook_clips(
 attachment TEXT PRIMARY KEY REFERENCES nook_attachments(id) ON DELETE CASCADE,
 message TEXT NOT NULL REFERENCES nook_messages(id) ON DELETE CASCADE,
 conversation TEXT NOT NULL REFERENCES nook_conversations(id),
 version INTEGER NOT NULL CHECK(version>=1),created TEXT NOT NULL,
 UNIQUE(attachment,message,conversation)
);
CREATE INDEX nook_clips_message ON nook_clips(message);
CREATE INDEX nook_clips_conversation ON nook_clips(conversation,attachment);
CREATE TABLE nook_clip_transcripts(
 attachment TEXT NOT NULL,message TEXT NOT NULL,conversation TEXT NOT NULL,
 version INTEGER NOT NULL CHECK(version>=1),actor TEXT,created TEXT NOT NULL,
 format TEXT NOT NULL CHECK(format IN ('typed','webvtt')),language TEXT NOT NULL,
 cues_json TEXT NOT NULL CHECK(json_valid(cues_json) AND json_type(cues_json)='array'),
 PRIMARY KEY(attachment,version),
 FOREIGN KEY(attachment,message,conversation) REFERENCES nook_clips(attachment,message,conversation) ON DELETE CASCADE
);
CREATE INDEX nook_clip_transcripts_actor ON nook_clip_transcripts(actor);
CREATE INDEX nook_clip_transcripts_message ON nook_clip_transcripts(message);
CREATE TRIGGER nook_clip_transcript_immutable BEFORE UPDATE ON nook_clip_transcripts
 WHEN NEW.attachment IS NOT OLD.attachment OR NEW.message IS NOT OLD.message OR NEW.conversation IS NOT OLD.conversation OR NEW.version IS NOT OLD.version OR NEW.created IS NOT OLD.created OR NEW.format IS NOT OLD.format OR NEW.language IS NOT OLD.language OR NEW.cues_json IS NOT OLD.cues_json OR (NEW.actor IS NOT OLD.actor AND NEW.actor IS NOT NULL)
 BEGIN SELECT RAISE(ABORT,'Transcript corrections require a new version'); END;
-- Explicit deletes also work in maintenance contexts without FK enforcement.
-- Erasure callers must collect portability row keys BEFORE these triggers run.
CREATE TRIGGER nook_clip_attachment_delete BEFORE DELETE ON nook_attachments BEGIN
 DELETE FROM nook_clip_transcripts WHERE attachment=OLD.id;
 DELETE FROM nook_clips WHERE attachment=OLD.id;
END;
CREATE TRIGGER nook_clip_message_delete BEFORE DELETE ON nook_messages BEGIN
 DELETE FROM nook_clip_transcripts WHERE message=OLD.id;
 DELETE FROM nook_clips WHERE message=OLD.id;
END;
CREATE TRIGGER nook_clip_delete BEFORE DELETE ON nook_clips BEGIN
 DELETE FROM nook_clip_transcripts WHERE attachment=OLD.attachment;
END;
CREATE TRIGGER nook_clip_actor_delete BEFORE DELETE ON nook_actors BEGIN
 UPDATE nook_clip_transcripts SET actor=NULL WHERE actor=OLD.id;
END;
CREATE TRIGGER nook_clips_exit_insert AFTER INSERT ON nook_clips BEGIN
 INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER nook_clips_exit_delete AFTER DELETE ON nook_clips BEGIN
 INSERT INTO nook_exit_changes VALUES(OLD.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER nook_clip_transcripts_exit_insert AFTER INSERT ON nook_clip_transcripts BEGIN
 INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER nook_clip_transcripts_exit_update AFTER UPDATE ON nook_clip_transcripts BEGIN
 INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER nook_clip_transcripts_exit_delete AFTER DELETE ON nook_clip_transcripts BEGIN
 INSERT INTO nook_exit_changes VALUES(OLD.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;
-- Import undo tombstones disclosed native file copies in place.
CREATE TRIGGER nook_clip_file_tombstone BEFORE UPDATE OF state ON nook_attachments WHEN NEW.state='deleted' BEGIN
 DELETE FROM nook_clip_transcripts WHERE attachment=OLD.id;
 DELETE FROM nook_clips WHERE attachment=OLD.id;
END;

-- NOOK-082 extends the existing schedule payload, runner and occurrence ledger.
-- No source body or attachment snapshot is held until the ordinary forward door
-- delivers. Source erasure cancels pending work and removes its derived request.
CREATE TRIGGER nook_scheduled_forward_source_delete BEFORE DELETE ON nook_messages BEGIN
 UPDATE nook_schedules SET state='cancelled',version=version+1,reason='Forward source was erased',
 payload=json_set(json_remove(payload,'$.forward'),'$.forwardErased',json('true')),definition=json_set(json_remove(definition,'$.payload.forward'),'$.payload.forwardErased',json('true'))
 WHERE json_extract(payload,'$.forward.source')=OLD.id;
END;
CREATE TRIGGER nook_scheduled_forward_import_delete BEFORE DELETE ON nook_import_records BEGIN
 UPDATE nook_schedules SET state='cancelled',version=version+1,reason='Forward source was erased',
 payload=json_set(json_remove(payload,'$.forward'),'$.forwardErased',json('true')),definition=json_set(json_remove(definition,'$.payload.forward'),'$.payload.forwardErased',json('true'))
 WHERE json_extract(payload,'$.forward.source')=OLD.id;
END;
CREATE TRIGGER nook_scheduled_forward_exit_insert AFTER INSERT ON nook_schedules BEGIN
 INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER nook_scheduled_forward_exit_update AFTER UPDATE ON nook_schedules BEGIN
 INSERT INTO nook_exit_changes VALUES(NEW.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER nook_scheduled_forward_exit_delete AFTER DELETE ON nook_schedules BEGIN
 INSERT INTO nook_exit_changes VALUES(OLD.conversation,1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1;
END;

CREATE TABLE nook_digest_schedules(
 user TEXT PRIMARY KEY,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),
 cadence TEXT NOT NULL CHECK(cadence IN('daily','weekly')),local_at TEXT NOT NULL,zone TEXT NOT NULL,
 delivery TEXT NOT NULL CHECK(delivery IN('app','email')),next_due INTEGER NOT NULL,
 version INTEGER NOT NULL,operator_version INTEGER NOT NULL,access_generation INTEGER NOT NULL,updated INTEGER NOT NULL
);
CREATE INDEX nook_digest_due ON nook_digest_schedules(enabled,next_due);
-- Receipts hold source IDs, hashes and quote offsets, never answer prose or text.
CREATE TABLE nook_digest_deliveries(
 id TEXT PRIMARY KEY,user TEXT NOT NULL,version INTEGER NOT NULL,local_at TEXT NOT NULL,due INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN('deferred','delivering','delivered','empty','failed','skipped')),
 reason TEXT,receipt TEXT CHECK(receipt IS NULL OR json_valid(receipt)),created INTEGER NOT NULL,updated INTEGER NOT NULL,
 UNIQUE(user,version,local_at)
);
CREATE TRIGGER nook_digest_message_delete BEFORE DELETE ON nook_messages BEGIN
 DELETE FROM nook_digest_deliveries WHERE EXISTS(SELECT 1 FROM json_each(receipt,'$.points') p WHERE json_extract(p.value,'$.id')='message:'||OLD.id);
END;
CREATE TRIGGER nook_digest_file_delete BEFORE DELETE ON nook_attachments BEGIN
 DELETE FROM nook_digest_deliveries WHERE EXISTS(SELECT 1 FROM json_each(receipt,'$.points') p WHERE json_extract(p.value,'$.id')='file:'||OLD.id);
END;
CREATE TRIGGER nook_digest_import_delete BEFORE DELETE ON nook_import_records BEGIN
 DELETE FROM nook_digest_deliveries WHERE EXISTS(SELECT 1 FROM json_each(receipt,'$.points') p WHERE json_extract(p.value,'$.id')='message:'||OLD.id);
END;
CREATE TRIGGER nook_digest_schedule_exit_insert AFTER INSERT ON nook_digest_schedules BEGIN INSERT INTO nook_exit_changes VALUES('',1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_digest_schedule_exit_update AFTER UPDATE ON nook_digest_schedules BEGIN INSERT INTO nook_exit_changes VALUES('',1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_digest_schedule_exit_delete AFTER DELETE ON nook_digest_schedules BEGIN INSERT INTO nook_exit_changes VALUES('',1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_digest_delivery_exit_insert AFTER INSERT ON nook_digest_deliveries BEGIN INSERT INTO nook_exit_changes VALUES('',1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_digest_delivery_exit_update AFTER UPDATE ON nook_digest_deliveries BEGIN INSERT INTO nook_exit_changes VALUES('',1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER nook_digest_delivery_exit_delete AFTER DELETE ON nook_digest_deliveries BEGIN INSERT INTO nook_exit_changes VALUES('',1) ON CONFLICT(conversation) DO UPDATE SET revision=revision+1; END;

-- Additive upgrade: personal keywords and their delivery choices. Every existing
-- preference row keeps its values; keyword push and email stay off until chosen
-- (a member's first push registration turns keyword push on with the other defaults).
CREATE TABLE nook_keywords(user TEXT NOT NULL,folded TEXT NOT NULL,keyword TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(user,folded));
CREATE TRIGGER nook_keywords_limit BEFORE INSERT ON nook_keywords WHEN (SELECT count(*) FROM nook_keywords WHERE user=NEW.user)>=20 BEGIN SELECT RAISE(ABORT,'keyword_limit'); END;
ALTER TABLE nook_notify_preferences ADD COLUMN push_keywords INTEGER NOT NULL DEFAULT 0 CHECK(push_keywords IN (0,1));
ALTER TABLE nook_notify_preferences ADD COLUMN keywords INTEGER NOT NULL DEFAULT 0 CHECK(keywords IN (0,1));
ALTER TABLE nook_notify_preferences ADD COLUMN keywords_in_muted INTEGER NOT NULL DEFAULT 0 CHECK(keywords_in_muted IN (0,1));

